const result = {};

for (const [key, value] of Object.entries($input.item.json)) {
  if (typeof value !== 'string') continue;

  const fragments = value.split("\n\n");
  for (let i = 0; i < fragments.length; i++)
    result[`${key}_${i + 1}`] = fragments[i];
}

return { json: { ...result } };
